var itemId = queryValue(baseUrl, 'q');
var bookId = queryValue(baseUrl, 'book_id') || GET.call(this, 'bookId');
var module = moduleFromUrl(baseUrl, GET.call(this, 'module') || 3);
try { book.type = bookTypeForModule(module); } catch (e) {}

// ===== 正文 =====
if (module == 3 || module == 13) {
  // ===== 气泡社区 =====
  // 社区气泡仅在 loginUi 手动同步时拉取，正文不做外部网络请求，
  // 避免社区站点抖动导致正文加载失败（v17）。
  var response = requestJSON.call(this, '/api/content?item_id=' + encodeURIComponent(itemId));
  result = response.data.content;

  var imgPlaceholders = [];
  result = String(result).replace(/<img[^>]*>/g, function(match) {
    var placeholder = 'IMG_' + imgPlaceholders.length + 'IMG';
    imgPlaceholders.push(match);
    return placeholder;
  });

  result = result.replace(/<\/p>/g, '\n').replace(/<[^>]+>/g, '').replace(/(IMG_\d+IMG)\n/g, '$1');
  result = result.split('\n').filter(function(item) { return item !== ''; }).join('\n');
  if (switchEnabled.call(this, 'showPara')) {
    result = getComments.call(this, result, bookId, itemId);
  }

  result = String(result).replace(/IMG_(\d+)IMG/g, function(match, index) {
    return imgPlaceholders[parseInt(index)] || match;
  });

  // ===== 正文尾部自定义内容 =====
  if (module == 3 || module == 13) {
    try {
      var footerResp = requestJSON.call(this, '/api/content_footer?module=' + encodeURIComponent(module));
      var footerText = footerResp && footerResp.data ? String(footerResp.data.content || '') : '';
      if (footerText) result = String(result || '') + '\n\n' + footerText;
    } catch (e) {}
  }
  var showChapterAction = switchEnabled.call(this, 'showChap');
  var showAuthorAction = switchEnabled.call(this, 'showAuthor');
  var showRelatedAction = switchEnabled.call(this, 'showBook');
  var availableActions = readerActionAvailability.call(this, bookId, itemId, {
    chapter: showChapterAction,
    author: showAuthorAction,
    related: showRelatedAction
  });
  if (showChapterAction && availableActions.chapter > 0) {
    var discussImage = createReaderActionBanner.call(this, 'chapter', availableActions.chapter);
    result += '\n<img src="' + discussImage + ',{"click":"getChapComments(\'' + bookId + '\',\'' + itemId + '\')","style":"full"}">';
  }
  if (showAuthorAction && availableActions.author > 0) {
    var authorImage = createReaderActionBanner.call(this, 'author', availableActions.author);
    result += '\n<img src="' + authorImage + ',{"click":"getAuthorSay(\'' + bookId + '\',\'' + itemId + '\')","style":"full"}">';
  }
  if (showRelatedAction && availableActions.related > 0) {
    var relatedImage = createReaderActionBanner.call(this, 'related', availableActions.related);
    result += '\n<img src="' + relatedImage + ',{"click":"openRelatedWorks(\'' + bookId + '\')","style":"full"}">';
  }
} else if (module == 2) {
  var tone = GET.call(this, 'tone') || 'tone_id=0';
  try {
    var audio = requestJSON.call(this, '/api/content?item_ids=' + encodeURIComponent(itemId) + '&' + tone + '&ts=%E5%90%AC%E4%B9%A6');
    result = audio.data.raw_url || (audio.data.backup_url || [])[0] || audio.data.content || '';
  } catch (e) {
    result = '';
  }
} else if (module == 8) {
  try {
    var manga = requestJSON.call(this, '/api/manga?item_id=' + encodeURIComponent(itemId));
    result = (manga.data.images || []).map(function(url) { return '<img src="' + url + '">'; }).join('\n');
  } catch (e) {
    result = '';
  }
} else if (module == 11 || module == 19) {
  try {
    var videoQuality = String(GET.call(this, 'videoQuality') || 'high');
    var qualityParams = videoQuality == 'low' ? '&quality=low&prefer_1080=0' : '&prefer_1080=1';
    var video = requestJSON.call(this, '/api/video?item_id=' + encodeURIComponent(itemId) + '&book_id=' + encodeURIComponent(bookId || '') + '&type=json' + qualityParams);
    result = video.data.raw_url || video.data.url || '';
  } catch (e) {
    result = '';
  }
}
result;

