function getHostList() {
  var source = this.source;
  var d = {};
  try { d = JSON.parse(source.getVariable() || "{}"); } catch (e) { d = {}; }
  var list = d['hosts'];
  if (!Array.isArray(list)) list = String(list || '').split(/\r?\n/);
  list = list.map(function(x) { return String(x || '').trim().replace(/\/+$/, ''); })
    .filter(function(x, i, arr) { return /^https?:\/\//i.test(x) && arr.indexOf(x) === i; });
  var sourceHost = String(source.bookSourceUrl || '').trim().replace(/\/+$/, '');
  if (!list.length && /^https?:\/\//i.test(sourceHost)) list.push(sourceHost);
  return list;
}

function buildApiUrl(path, host) {
  var source = this.source;
  var base = String(host || GET.call(this, 'server') || source.bookSourceUrl || '').trim().replace(/\/+$/, '');
  var url = base + (String(path || '').startsWith('/') ? path : '/' + path);
  var key = GET.call(this, 'api_key');
  if (!key) {
    try { key = (source.getLoginInfoMap() || {})['API密钥'] || ''; } catch (e) {}
  }
  if (key && !/[?&]api_key=/.test(url)) url += (url.indexOf('?') >= 0 ? '&' : '?') + 'api_key=' + encodeURIComponent(key);
  return url;
}

function autoSetHost(force) {
  var java = this.java;
  var list = getHostList.call(this);
  if (!list.length) return '';
  var current = String(GET.call(this, 'server') || '');
  var lastCheck = Number(GET.call(this, 'server_check_time') || 0);
  if (!force && current && Date.now() - lastCheck < 60000) return current;
  var start = Number(GET.call(this, 'server_id') || 0) % list.length;
  for (var i = 0; i < list.length; i++) {
    var id = (start + i) % list.length;
    try {
      var root = JSON.parse(java.ajax(buildApiUrl.call(this, '/api/health', list[id])));
      if (root && root.code === 0) {
        SET.call(this, 'server', list[id]);
        SET.call(this, 'server_id', id);
        SET.call(this, 'server_check_time', Date.now());
        return list[id];
      }
    } catch (e) {}
  }
  return current || list[0];
}

function API(path) {
  return buildApiUrl.call(this, path, autoSetHost.call(this, false));
}

function requestJSON(path) {
  var java = this.java;
  var list = getHostList.call(this);
  var current = String(GET.call(this, 'server') || '');
  var start = Math.max(0, list.indexOf(current));
  var lastError = '';
  for (var i = 0; i < list.length; i++) {
    var id = (start + i) % list.length;
    try {
      var root = JSON.parse(java.ajax(buildApiUrl.call(this, path, list[id])));
      SET.call(this, 'server', list[id]);
      SET.call(this, 'server_id', id);
      SET.call(this, 'server_check_time', Date.now());
      if (!root || root.code !== 0) throw new Error((root && root.msg) || '接口返回异常');
      return root;
    } catch (e) { lastError = String(e); }
  }
  throw new Error(lastError || '所有服务器均不可用');
}

function queryValue(url, name) {
  var match = String(url || '').match(new RegExp('[?&]' + name + '=([^&]+)', 'i'));
  if (!match) return '';
  try { return decodeURIComponent(match[1]); } catch (e) { return match[1]; }
}

function moduleFromUrl(url, fallback) {
  var value = Number(queryValue(url, 'ys_module') || fallback || 3);
  return [2, 3, 8, 11, 13, 19].indexOf(value) >= 0 ? value : 3;
}

function moduleFromCurrentResult(fallback) {
