function switchEnabled(name) {
  var source = this.source; var cache = this.cache;
  var config = {};
  try { config = JSON.parse(source.getVariable() || '{}'); } catch (e) {}
  try {
    var cached = JSON.parse(cache.get('pyfqSourceConfig:' + encodeURIComponent(String(source.bookSourceUrl || ''))) || '{}');
    if (Object.prototype.hasOwnProperty.call(cached, name)) config[name] = cached[name];
  } catch (e1) {}
  var value = Object.prototype.hasOwnProperty.call(config, name) ? config[name] : GET.call(this, name);
  if (Number(config.commentDefaultsVersion || 0) < 2 && ['showPara','showChap','showAuthor'].indexOf(name) >= 0) value = true;
  return value === true || String(value).toLowerCase() == 'true' || String(value) == '1';
}

function currentBookId(pageUrl, currentBook) {
  var candidates = [pageUrl];
  try { candidates.push(currentBook.bookUrl); } catch (e0) {}
  try { candidates.push(currentBook.origin); } catch (e1) {}
  for (var i = 0; i < candidates.length; i++) {
    var value = String(candidates[i] || '');
    var id = queryValue(value, 'book_id');
    if (id) return id;
    var match = value.match(/(?:^|[^0-9])([0-9]{15,22})(?:[^0-9]|$)/);
    if (match) return match[1];
  }
  return String(GET.call(this, 'bookId') || '');
}

function readerActionRows(value, names, maxDepth) {
  var rows = [];
  function walk(node, depth) {
    if (!node || depth < 0 || typeof node !== 'object') return;
    if (Array.isArray(node)) {
      node.forEach(function(item) { walk(item, depth - 1); });
      return;
    }
    Object.keys(node).forEach(function(key) {
      var child = node[key];
      if (names.indexOf(key) >= 0 && Array.isArray(child)) {
        child.forEach(function(item) { if (item) rows.push(item); });
      } else if (child && typeof child === 'object') {
        walk(child, depth - 1);
      }
    });
  }
  walk(value, Number(maxDepth || 6));
  return rows;
}

function readerActionHasBody(value) {
  var queue = [value];
  var wrappers = ['comment','post','topic','common','content','chapter_data','chapter_info','author_say'];
  for (var depth = 0; depth < 4 && queue.length; depth++) {
    var next = [];
    for (var i = 0; i < queue.length; i++) {
      var item = queue[i];
      if (typeof item === 'string' && item.replace(/\s+/g, '') !== '') return true;
      if (!item || typeof item !== 'object') continue;
      var textKeys = ['text','content','title','description','abstract','post_content','message','author_content','pure_content','topic_content','topic_title'];
      for (var j = 0; j < textKeys.length; j++) {
        var text = item[textKeys[j]];
        if (typeof text === 'string' && text.replace(/\s+/g, '') !== '') return true;
        if (text && typeof text === 'object') next.push(text);
      }
      var mediaKeys = ['image_data_list','image_list','images','image_url','video_url'];
      for (var m = 0; m < mediaKeys.length; m++) {
        var media = item[mediaKeys[m]];
        if ((Array.isArray(media) && media.length) || (typeof media === 'string' && media !== '')) return true;
      }
      wrappers.forEach(function(key) { if (item[key] && typeof item[key] === 'object') next.push(item[key]); });
    }
    queue = next;
  }
  return false;
}

function readerActionAvailability(bookId, itemId, enabled) {
  var result = {chapter: 0, author: 0, related: 0};
  if (enabled.chapter) {
    try {
      var forumRoot = requestJSON.call(this, '/api/forum_id?book_id=' + encodeURIComponent(bookId) + '&item_id=' + encodeURIComponent(itemId));
      var forumPayload = forumRoot.data || forumRoot;
      var forum = forumPayload.forum_data || forumPayload.data || forumPayload;
      var forumId = String(forum.forum_id || '');
      if (forumId) {
        var commentRoot = requestJSON.call(this, '/api/end_comments?book_id=' + encodeURIComponent(bookId) + '&item_id=' + encodeURIComponent(itemId) + '&forum_id=' + encodeURIComponent(forumId) + '&count=30&offset=0');
        result.chapter = readerActionRows(commentRoot.data || commentRoot, ['mix_data','data_list','post_list','topic_list','comment_list','items','list'], 7).length;
      }
    } catch (chapterError) {}
  }
  if (enabled.author) {
    try {
      var authorRoot = requestJSON.call(this, '/api/author_say?book_id=' + encodeURIComponent(bookId) + '&item_id=' + encodeURIComponent(itemId));
      var authorPayload = authorRoot.data || authorRoot;
      var authorRows = readerActionRows(authorPayload, ['chapter_data_list','data_list','author_say_list','content_list','item_list'], 7)
        .filter(function(row) { return readerActionHasBody(row); });
      if (authorPayload.topic && readerActionHasBody(authorPayload.topic)) authorRows.push(authorPayload.topic);
      result.author = authorRows.length;
    } catch (authorError) {}
  }
  if (enabled.related) {
    try {
      var relatedRoot = requestJSON.call(this, '/api/recommendations?book_id=' + encodeURIComponent(bookId));
      var relatedPayload = relatedRoot.data || relatedRoot;
      result.related = Array.isArray(relatedPayload.book_info) ? relatedPayload.book_info.length : 0;
    } catch (relatedError) {}
  }
  return result;
}
